      nodes: [
        { id: 'request', label: 'INCOMING REQUEST', title: 'Classify Complexity', sub: 'Route to cheapest model that can handle it', color: 'blue',
          code: `${CM('# Cost-optimised routing endpoint')}\n${DE('@app.post')}(${ST('"/smart/chat"')})\n${KW('async def')} ${FN('smart_chat')}(req: ${TP('ChatRequest')}) -> ${TP('ChatResponse')}:\n    complexity = ${FN('classify_complexity')}(req.message)\n    trimmed    = ${FN('trim_to_budget')}(req.message)\n    batched    = ${KW('await')} ${FN('maybe_batch')}(trimmed, complexity)\n    ${KW('return')} batched` },
        { id: 'classify', label: 'ROUTE?', title: 'Route?', sub: 'simple / medium / complex', color: 'amber', isDiamond: true,
          code: `${CM('# Heuristic complexity classifier')}\n${KW('def')} ${FN('classify_complexity')}(prompt: ${TP('str')}) -> ${TP('str')}:\n    words = len(prompt.split())\n    ${CM('# Simple heuristics — replace with tiny LLM for prod')}\n    ${KW('if')} words < ${NU('20')} ${KW('and')} ${KW('not')} ${FN('needs_reasoning')}(prompt):\n        ${KW('return')} ${ST('"simple"')}    ${CM('# → gpt-4o-mini ($0.15/1M in)')}\n    ${KW('elif')} words < ${NU('100')} ${KW('or')} ${FN('is_domain_specific')}(prompt):\n        ${KW('return')} ${ST('"medium"')}    ${CM('# → DeepSeek ($0.14/1M in)')}\n    ${KW('else')}:\n        ${KW('return')} ${ST('"complex"')}   ${CM('# → gpt-4o ($2.50/1M in)')}` },
        { id: 'small', label: 'SIMPLE', title: 'gpt-4o-mini', sub: '$0.15 / 1M tokens · ~300ms', color: 'green',
          code: `${CM('# Model routing map')}\nMODEL_ROUTING = {\n    ${ST('"simple"')}:  ${ST('"gpt-4o-mini"')},    ${CM('# $0.15/1M input,  $0.60/1M output')}\n    ${ST('"medium"')}:  ${ST('"deepseek-chat"')},   ${CM('# $0.14/1M input,  $0.28/1M output')}\n    ${ST('"complex"')}: ${ST('"gpt-4o"')},          ${CM('# $2.50/1M input, $10.00/1M output')}\n}\n\n${KW('async def')} ${FN('route_to_model')}(prompt: ${TP('str')}, complexity: ${TP('str')}) -> ${TP('str')}:\n    model = MODEL_ROUTING[complexity]\n    ${KW('return')} ${KW('await')} ${FN('llm_call')}(prompt, model=model)` },
        { id: 'trimmer', label: 'TOKEN BUDGET', title: 'Prompt Trimmer', sub: 'System ≤200 · Context ≤2000 · max_tokens=512', color: 'purple',
          code: `${CM('# Token budget trimmer — prevent runaway costs')}\n${KW('import')} tiktoken\n\nenc = tiktoken.${FN('encoding_for_model')}(${ST('"gpt-4o-mini"')})\n\n${KW('def')} ${FN('trim_to_budget')}(\n    prompt: ${TP('str')},\n    max_tokens: ${TP('int')} = ${NU('2000')}\n) -> ${TP('str')}:\n    tokens = enc.encode(prompt)\n    ${KW('if')} len(tokens) <= max_tokens:\n        ${KW('return')} prompt\n    trimmed = enc.decode(tokens[:max_tokens])\n    ${KW('return')} trimmed + ${ST('"... [truncated]"')}` },
        { id: 'batch', label: 'BATCHING', title: 'Request Batcher', sub: 'Batch embeddings 100/call · async gather', color: 'teal',
          code: `${CM('# Batch embeddings — 100x cost reduction')}\n${KW('async def')} ${FN('batch_embed')}(texts: list[${TP('str')}], batch_size=${NU('100')}) -> list:\n    all_vecs = []\n    ${KW('for')} i ${KW('in')} range(${NU('0')}, len(texts), batch_size):\n        batch = texts[i:i+batch_size]\n        resp  = ${KW('await')} client.embeddings.create(\n            model=${ST('"text-embedding-3-small"')},  ${CM('# $0.02/1M tokens')}\n            input=batch,\n        )\n        all_vecs.extend([e.embedding ${KW('for')} e ${KW('in')} resp.data])\n    ${KW('return')} all_vecs` },
      ]
